const generatorResponse = $('Call GPT-5.6 - Canvas Generation').first().json;
const meta = $('Parse Plan & Build Canvas Prompt').first().json;

const raw = generatorResponse.choices?.[0]?.message?.content;
if (!raw) throw new Error('No canvas code from generator: ' + JSON.stringify(generatorResponse));

let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();
}

function fixJsonEscapes(str) {
  return str.replace(/\\(?!["\\/bfnrtu])/g, '\\\\');
}

let parsed;
try { parsed = JSON.parse(cleaned); }
catch(e) {
  try { parsed = JSON.parse(fixJsonEscapes(cleaned)); }
  catch(e2) { throw new Error('Could not parse canvas codes JSON. First 400 chars: ' + cleaned.substring(0, 400)); }
}

const slides = parsed.slides || [];
if (slides.length === 0) throw new Error('No slides in canvas generation response');

// Logo behavior is owned by each layout JSON, never by a global theme toggle.
// No logo-related key means no logo. Explicit logo.variant wins; otherwise the
// layout's color mode selects the matching brand logo variant.
const slots = meta.slots || [];
function logoVariantForSlot(slot) {
  const rawLayout = slot?.layout_json;
  if (!rawLayout || !/logo/i.test(rawLayout)) return 'none';
  let layout;
  try { layout = typeof rawLayout === 'string' ? JSON.parse(rawLayout) : rawLayout; }
  catch { return 'none'; }

  const logo = layout.logo ?? layout.brandLogo ?? layout.logoConfig;
  if (logo === false || logo === null || logo === 'none' || logo?.enabled === false) return 'none';
  const mentionedInElements = Array.isArray(layout.elements) && layout.elements.some(el =>
    /logo/i.test(String(el?.type || el?.role || el?.name || el?.id || '')) && el?.enabled !== false
  );
  if (logo === undefined && !mentionedInElements) return 'none';

  const explicit = typeof logo === 'string' ? logo : logo?.variant;
  if (explicit === 'light' || explicit === 'dark') return explicit;
  const mode = String(layout.theme || layout.colorMode || layout.background?.theme || layout.background?.mode || '').toLowerCase();
  return mode === 'dark' ? 'dark' : 'light';
}

// Resolved position for the app's own deterministic logo overlay (see
// logoVariantForSlot above for why the AI never draws this itself).
function logoPositionForSlot(slot) {
  const rawLayout = slot?.layout_json;
  if (!rawLayout) return null;
  let layout;
  try { layout = typeof rawLayout === 'string' ? JSON.parse(rawLayout) : rawLayout; }
  catch { return null; }
  const logo = layout.logo ?? layout.brandLogo ?? layout.logoConfig;
  if (!logo || logo === false || logo === 'none' || logo?.enabled === false || typeof logo !== 'object') return null;
  const height = Number(logo.height);
  const y = Number(logo.y);
  if (!Number.isFinite(height) || !Number.isFinite(y)) return null;
  const x = (logo.x === 'center' || logo.align === 'center') ? 'center' : Number(logo.x);
  if (x !== 'center' && !Number.isFinite(x)) return null;
  return { x, y, height };
}

// Per-slide canvas size — read from each slot's own "canvas" key in its
// layout JSON (default 1080x1080 if missing/invalid). Slides can differ.
function canvasSizeForSlot(slot) {
  const rawLayout = slot?.layout_json;
  if (!rawLayout) return { width: 1080, height: 1080 };
  let layout;
  try { layout = typeof rawLayout === 'string' ? JSON.parse(rawLayout) : rawLayout; }
  catch { return { width: 1080, height: 1080 }; }
  const width = Number(layout?.canvas?.width);
  const height = Number(layout?.canvas?.height);
  return {
    width: Number.isFinite(width) && width > 0 ? width : 1080,
    height: Number.isFinite(height) && height > 0 ? height : 1080,
  };
}

const jsCodes = slides.map((slide, i) => {
  const { width, height } = canvasSizeForSlot(slots[i]);
  return {
    ...slide,
    logoVariant: logoVariantForSlot(slots[i]),
    logoPosition: logoPositionForSlot(slots[i]),
    canvasWidth: width,
    canvasHeight: height,
  };
});
return [{ json: {
  jsCodes,
  brandId: $('Webhook').first().json.body.brandId,
  brandName: meta.brandName,
} }];

const body = $('Webhook').first().json.body;
const brandData = $('Fetch Brand Data').first().json;
const brandName = brandData.brands?.name || 'Unknown Brand';
const brandStyle = brandData.blog_md || brandData.infographic_md || brandData.style_prompt || '';
const filename = body.filename || 'document.pdf';
const pdfBase64 = $('Prepare PDF Data').first().json.pdfBase64;
if (!pdfBase64) throw new Error('No prepared PDF data available');

// A Layout Group's ordered Slots are required — they define slide count and
// per-slide content purpose. There is no freeform fallback.
if (!body.layoutGroupId) throw new Error('No JSON layout selected');

const rawSlots = $('Fetch Blog Layout Slots').all().map(r => r.json);
const slots = rawSlots
  .filter(s => s.group_id === body.layoutGroupId)
  .sort((a, b) => a.slot_index - b.slot_index);

if (slots.length === 0) throw new Error('No JSON layout found');

const slotLines = slots.map((s, i) =>
  '  Slide ' + (i + 1) + ' (' + s.name + '): ' + (s.description || 'No specific purpose given — use best judgement from the PDF.')
).join('\n');

// Admin-editable in Brand Settings → "Blog Plan Prompt" (brand_profiles.blog_plan_prompt).
// Supports tokens: {{slideCount}}, {{slotLines}}. Falls back to this default when unset.
const DEFAULT_PLAN_PROMPT = [
  'You are a content strategist analyzing PDF documents to plan visual blog image slide decks.',
  '',
  'Analyze the PDF and plan exactly {{slideCount}} blog image slides, in this exact order:',
  '{{slotLines}}',
  '',
  'Rules:',
  '  - Exactly {{slideCount}} slides, in the order given above — do not reorder or skip any.',
  '  - Extract content ONLY from the PDF. Do not invent data.',
  '  - Keep text concise: these become compact social-media-sized images.',
  '  - Where a slide purpose mentions a statistic or quote, pull real numbers/verbatim text from the PDF.',
  '',
  'Return ONLY a valid JSON object - no markdown, no code fences.',
].join('\n');

const planTemplate = (brandData.blog_plan_prompt && brandData.blog_plan_prompt.trim()) || DEFAULT_PLAN_PROMPT;
const systemPrompt = planTemplate
  .split('{{slideCount}}').join(String(slots.length))
  .split('{{slotLines}}').join(slotLines);

const requestBody = JSON.stringify({
  model: 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: [
      { type: 'image_url', image_url: { url: 'data:application/pdf;base64,' + pdfBase64 } },
      { type: 'text', text: 'PDF filename: ' + filename + '\nBrand: ' + brandName + '\n\nAnalyze this PDF and plan ' + slots.length + ' blog image slides.' }
    ]}
  ],
  response_format: { type: 'json_object' },
  max_tokens: 8000
});

return [{ json: { requestBody, brandName, brandStyle, brandData, filename, slots } }];

const planResponse = $('Call Gemini Flash - Content Plan').first().json;
const meta = $('Build Content Plan Prompt').first().json;
const brandData = meta.brandData;
const slots = meta.slots || [];

function extractContentPlan(response) {
  const raw = response?.choices?.[0]?.message?.content;
  if (!raw) return null;
  let cleaned = raw.trim();
  if (cleaned.startsWith('`')) cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();
  try {
    const parsed = JSON.parse(cleaned);
    if (Array.isArray(parsed.slides) && parsed.slides.length > 0) return parsed;
  } catch { /* invalid JSON on this attempt — caller decides whether to retry */ }
  return null;
}

let contentPlan = extractContentPlan(planResponse);

if (!contentPlan) {
  // The HTTP node's retryOnFail only covers network-level failures. A 200
  // response with an empty/invalid "slides" array sails right past that and
  // used to kill the whole job here. Retry the same prompt once, with an
  // explicit nudge, before giving up for real.
  const retryRequestBody = JSON.parse(meta.requestBody);
  retryRequestBody.messages.push({
    role: 'user',
    content: 'Your previous response had no valid non-empty "slides" array. Return ONLY the JSON object again, this time with a populated "slides" array covering every slide.',
  });
  let retryResponse;
  try {
    retryResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: {
        'Authorization': 'Bearer __OPENAI_API_KEY__',
        'Content-Type': 'application/json',
        'HTTP-Referer': 'https://contentbeta.app',
        'X-Title': 'ContentBeta Blog Images Planner',
      },
      body: retryRequestBody,
      json: true,
      timeout: 180000,
    });
  } catch (retryErr) {
    throw new Error('AI returned no slides in the content plan, and the retry request itself failed: ' + (retryErr?.message || retryErr));
  }
  contentPlan = extractContentPlan(retryResponse);
  if (!contentPlan) {
    throw new Error('AI returned no slides in the content plan, even after one retry. Last response: ' + JSON.stringify(retryResponse).slice(0, 500));
  }
}

const slides = contentPlan.slides;

const fontHeading = brandData.infographic_font_heading || null;
const fontBody = brandData.infographic_font_body || null;
const logoUrl = brandData.infographic_logo_light_url || brandData.logo_url || null;

// Per-slide canvas size — read from each slot's own "canvas" key in its layout
// JSON (default 1080x1080 if missing/invalid). Sizes can differ slide to slide.
function canvasSizeForSlot(slot) {
  const rawLayout = slot?.layout_json;
  if (!rawLayout) return { width: 1080, height: 1080 };
  let layout;
  try { layout = typeof rawLayout === 'string' ? JSON.parse(rawLayout) : rawLayout; }
  catch { return { width: 1080, height: 1080 }; }
  const width = Number(layout?.canvas?.width);
  const height = Number(layout?.canvas?.height);
  return {
    width: Number.isFinite(width) && width > 0 ? width : 1080,
    height: Number.isFinite(height) && height > 0 ? height : 1080,
  };
}

const canvasSizeNote = slides.map((s, i) => {
  const { width, height } = canvasSizeForSlot(slots[i]);
  const safeRight = width - 72;
  const safeBottom = height - 72;
  const contentBottom = height - 100;
  return '  Slide ' + (s.slideNumber || i + 1) + ': ' + width + 'x' + height + 'px. Safe area: x 72-' + safeRight + ', y 72-' + safeBottom + '. Content bottom limit: ' + contentBottom + '.';
}).join('\n');

// Per-slide structural JSON from the selected Layout Group's slots — a strong
// hint to the AI (not a compiled/enforced schema), spliced into the prompt below.
const structureBlocks = slides.map((s, i) => {
  const slot = slots[i];
  if (!slot || !slot.layout_json) return '';
  return 'Slide ' + (s.slideNumber || i + 1) + ' STRUCTURE REFERENCE (JSON) — follow this element layout/positions/hierarchy precisely when authoring drawSlide:\n' + slot.layout_json;
}).filter(Boolean).join('\n\n');

const structureReferences = structureBlocks
  ? 'STRUCTURE REFERENCES — when a slide below has one, follow its JSON element layout/positions/hierarchy as closely as the canvas API allows:\n' + structureBlocks + '\n'
  : '';
const headingFontLine = fontHeading ? '  Heading font: "' + fontHeading + '"' : '  Use Inter, sans-serif for headings';
const bodyFontLine = fontBody ? '  Body font: "' + fontBody + '"' : '  Use Inter, sans-serif for body';

// Tell the AI where the app will place the logo so it leaves that area clear,
// without asking the AI to compute or draw the logo itself (see LOGO rule below).
const logoReservedNote = slides.map((s, i) => {
  const slot = slots[i];
  if (!slot || !slot.layout_json) return '';
  let layout;
  try { layout = typeof slot.layout_json === 'string' ? JSON.parse(slot.layout_json) : slot.layout_json; }
  catch { return ''; }
  const logo = layout?.logo ?? layout?.brandLogo ?? layout?.logoConfig;
  if (!logo || logo === false || logo === 'none' || logo?.enabled === false) return '';
  const xDesc = (logo.x === 'center' || logo.align === 'center') ? 'horizontally centered' : ('x≈' + logo.x);
  return '  Slide ' + (s.slideNumber || i + 1) + ': reserve space around y≈' + logo.y + ', ~' + logo.height + 'px tall, ' + xDesc + ' — keep other content clear of that area.';
}).filter(Boolean).join('\n');

// Admin-editable in Brand Settings → "Blog Canvas Prompt" (brand_profiles.blog_canvas_prompt).
// Supports tokens: {{slideCount}}, {{canvasSizeNote}}, {{structureReferences}}, {{headingFontLine}}, {{bodyFontLine}}, {{logoReservedNote}}.
const DEFAULT_CANVAS_PROMPT = [
  'You are a Creative Technologist generating JavaScript Canvas API code for branded static blog images.',
  'Generate exactly {{slideCount}} distinct blog image slides from the content plan. Each slide has its OWN canvas size — sizes can differ between slides:',
  '{{canvasSizeNote}}',
  '',
  'CRITICAL TECHNICAL RULES:',
  '1. Output ONLY a valid JSON object - no markdown, no code fences:',
  '   { "slides": [{ "slideNumber": N, "title": "...", "jsCode": "..." }] }',
  '2. Each jsCode is a named function: function drawSlide(ctx, width, height, logoImg, options) { ... }',
  '3. Canvas size VARIES PER SLIDE — see the sizes listed above. NEVER hardcode a fixed canvas size or safe-area pixel numbers.',
  '   ALWAYS compute margins from the width/height parameters actually passed into drawSlide, e.g.:',
  '     const safeRight = width - 72; const safeBottom = height - 72; const contentBottom = height - 100;',
  '4. STATIC images only - no animation. options is an empty object; do not read options.theme.',
  '5. Path2D: ALWAYS ctx.fill(path) and ctx.stroke(path). NEVER path.fill() or path.stroke().',
  '6. Use ctx.roundRect() - NOT ctx.roundedRect().',
  '7. Declare ALL variables with const/let before use.',
  '8. STRING LITERALS — Use double quotes for ALL string content. NEVER single quotes for strings. Apostrophes in string content WILL cause SyntaxError.',
  '9. VARIABLE NAMES — camelCase ONLY. No hyphens: wrapText not wrap-text.',
  '',
  'NO GLOBAL SCALE TRANSFORM — FORBIDDEN (prevents stretched/distorted text and shapes):',
  '  Do NOT write const sx = width / 1080; const sy = height / 1080; ctx.scale(sx, sy); or anything equivalent.',
  '  Canvas sizes are NOT always square (see the sizes listed above) — sx and sy will differ whenever width ≠ height,',
  '  and a non-uniform ctx.scale() stretches every shape and every glyph of text unevenly on that slide. This is a real bug seen in production.',
  '  Instead, compute every position and size directly from the real width/height parameters using plain arithmetic',
  '  (e.g. const marginX = 72; const cardW = (width - 144) / 4; const titleY = height * 0.08) — never through a global transform matrix.',
  '  ctx.scale()/ctx.setTransform() are allowed only for a LOCAL, UNIFORM change (same factor on both axes) around a single element — never as a whole-slide 1080-to-actual-size adapter.',
  '',
  'FILL THE ACTUAL CANVAS — MANDATORY (a real bug seen in production: content boxed into the top-left corner, leaving the rest of a larger canvas blank):',
  '  Removing ctx.scale() is not enough on its own — you must also derive every coordinate from width/height, not from memorized ~1080px numbers.',
  '  WRONG (hardcoded, assumes a ~1080px-wide canvas, breaks on a 1779x2048 or any other real size):',
  '    const centerX = 540; const colW = 456; const gridX = 72; const rowH = 160;',
  '  RIGHT (derived from the real parameters, fills whatever size this slide actually is):',
  '    const centerX = width / 2; const margin = 72; const gap = 24;',
  '    const colW = (width - margin * 2 - gap) / 2;',
  '    const rowH = (height - currentY - margin) / numRows; // sized so the rows actually reach the bottom margin',
  '  Every width, height, x, y, radius, and font size that depends on the canvas size must be an expression using width/height — never a bare number copied from a different slide size.',
  '',
  'TEXT ALIGNMENT — MANDATORY (prevents text running off the left edge):',
  '  Pick ONE centering method per text block, never both:',
  '  (a) Set ctx.textAlign = \'center\' and pass the true center-X straight to fillText for every line, with NO manual x offset math, OR',
  '  (b) Leave/set ctx.textAlign = \'left\' and manually compute lineX = centerX - measureText(line).width / 2 yourself.',
  '  If a helper function already does manual centering math (option b), ctx.textAlign MUST be \'left\' when it runs — never \'center\'.',
  '  Setting textAlign=\'center\' AND manually offsetting x by half the text width in the same draw double-centers the line and pushes it off-canvas.',
  '',
  'FONT MEASUREMENT — MANDATORY:',
  '  Always call ctx.measureText() with the exact ctx.font that was (or will be) used to render that text.',
  '  Never change ctx.font and then measure a string that was drawn, or will be drawn, in a different font — the width will be wrong and text will overlap.',
  '',
  'MEASURE-THEN-DRAW — MANDATORY:',
  '  If you need a text block’s wrapped height before drawing it (e.g. to vertically center content), write a SEPARATE pure-measurement helper',
  '  that only calls ctx.measureText() and returns line count × lineHeight — it must NOT call ctx.fillText().',
  '  Never call your drawing function once to \'measure\' and again to \'draw\': fillText draws immediately, so this leaves a duplicate/ghost copy of the text on the canvas.',
  '',
  '{{structureReferences}}',
  'LAYOUT COLORS — ONE FIXED TREATMENT PER SLIDE:',
  '  Use background, surface, text, accent, and border colors from that slide STRUCTURE REFERENCE.',
  '  Do not generate theme alternatives and do not read options.theme.',
  '',
  'LOGO — DO NOT DRAW IT YOURSELF:',
  '  The application composites the brand logo automatically after your code runs. NEVER call ctx.drawImage for a logo, and ignore the logoImg parameter entirely — treat it as always null.',
  '  {{logoReservedNote}}',
  '',
  'TYPOGRAPHY:',
  '{{headingFontLine}}',
  '{{bodyFontLine}}',
  '  Hero title: 60-72px bold | Stat number: 110-130px | Headline: 36-48px | Body: 22-28px',
  '  TEXT WRAPPING - MANDATORY: use measureText loop for all text blocks.',
  '',
  'LAYOUT RULES:',
  '  - 72px margin all sides (computed from that slide\'s own width/height — see rule 3). Content starts y>=200. Bottom <= height-100.',
  '  - Each slide must look DIFFERENT. Every slide complete as standalone, sized exactly per its own listed canvas size.',
  '',
  'ELEMENT STACKING — MANDATORY to prevent overlaps:',
  '  Use a currentY variable to track vertical position for ALL stacked elements:',
  '    let currentY = 200; // start below logo',
  '    // draw element at currentY',
  '    currentY += elementHeight + gap;',
  '  NEVER hardcode Y coordinates for elements that follow other elements.',
  '  Card bottom = cardY + cardH must be <= height-100 (computed, never hardcoded).',
  '',
  'TEXTBASELINE — MANDATORY:',
  '  Set ctx.textBaseline = \'top\' at the start of EVERY block that draws text.',
  '  After ctx.save()/ctx.restore(), textBaseline silently reverts — always re-set it.',
  '  With alphabetic baseline, text drawn at y=300 actually starts ~50px ABOVE y=300.',
  '',
  'SHADOW RESET — after every shadowed draw:',
  '  ctx.shadowColor = \'transparent\'; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;',
].join('\n');

const canvasTemplate = (brandData.blog_canvas_prompt && brandData.blog_canvas_prompt.trim()) || DEFAULT_CANVAS_PROMPT;
const systemPrompt = canvasTemplate
  .split('{{slideCount}}').join(String(slides.length))
  .split('{{canvasSizeNote}}').join(canvasSizeNote)
  .split('{{structureReferences}}').join(structureReferences)
  .split('{{headingFontLine}}').join(headingFontLine)
  .split('{{bodyFontLine}}').join(bodyFontLine)
  .split('{{logoReservedNote}}').join(logoReservedNote || 'No logo reserved for this deck.') + '\n\nFINAL LAYOUT CONTRACT (overrides any theme/logo instructions above): Use one fixed color treatment per slide from its STRUCTURE REFERENCE. Do not read options.theme and do not generate light/dark alternatives. The layout JSON is the source of truth for background and colors. Never draw a logo yourself and never call ctx.drawImage for a logo — the application composites the brand logo after your code runs. Only reserve/avoid the noted logo area so your other content does not overlap it. Each slide has its own canvas size (see the list above) — never assume a fixed size, always use the width/height parameters passed into drawSlide.';

const slideSummary = slides.map(s =>
  'Slide ' + s.slideNumber + ' (' + s.slideType + '): "' + s.title + '"' +
  (s.headline ? ' - ' + s.headline : '') +
  (s.stat ? ' - Stat: ' + s.stat : '') +
  (s.keyPoints?.length ? ' - Points: ' + s.keyPoints.slice(0,3).join(', ') : '')
).join('\n');

const userPrompt = [
  'Brand: ' + meta.brandName,
  'Brand Guidelines: ' + (meta.brandStyle || 'Use clean professional design.'),
  '',
  'Content Plan (' + slides.length + ' slides):',
  slideSummary,
  '',
  JSON.stringify(contentPlan, null, 2),
  '',
  'Generate all ' + slides.length + ' drawSlide functions as a JSON slides array.',
].join('\n');

const requestBody = JSON.stringify({
  model: 'gpt-5.6-terra',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  max_completion_tokens: 32000,
  // Low reasoning keeps the final code-generation stage responsive.
  reasoning_effort: 'low',
  response_format: { type: 'json_object' }
});

return [{ json: { requestBody, contentPlan, slides, slots, brandData, brandName: meta.brandName, brandStyle: meta.brandStyle, logoUrl } }];

const binary = $input.first().binary;
if (!binary?.data) throw new Error('No PDF binary data was fetched');

// n8n may store binary payloads on disk (binary.data.data is then only
// "filesystem-v2"). Read the real bytes through the supported helper.
const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!pdfBuffer?.length) throw new Error('Fetched PDF was empty');

return [{ json: { pdfBase64: pdfBuffer.toString('base64') } }];
